nds and only perform available actions.", "skills": [], "tools": [{"effect": "READ", "tool_id": "knowledge_search"}, {"effect": "READ", "tool_id": "service_episode_search"}, {"effect": "READ", "tool_id": "order_lookup"}, {"effect": "READ", "tool_id": "refund_status"}, {"effect": "READ", "tool_id": "refund_eligibility_check"}, {"effect": "WRITE", "tool_id": "refund_request_create"}, {"effect": "READ", "tool_id": "media_read"}, {"effect": "READ", "tool_id": "media_observe"}]}, {"action_proposals": [{"action_ref": "account.freeze:v1", "approval_policy": "EXPLICIT_CONFIRMATION_REQUIRED", "effect": "WRITE"}], "agent_id": "account_security", "description": "Assess account security concerns; distinguish user reports from verified facts.", "skills": [], "tools": [{"effect": "READ", "tool_id": "service_episode_search"}, {"effect": "READ", "tool_id": "account_security_event_list"}, {"effect": "READ", "tool_id": "account_security_state"}, {"effect": "READ", "tool_id": "account_freeze_status"}, {"effect": "WRITE", "tool_id": "account_freeze"}, {"effect": "READ", "tool_id": "media_read"}, {"effect": "READ", "tool_id": "media_observe"}]}, {"action_proposals": [{"action_ref": "support.handoff.create:v1", "approval_policy": "USER_COMMAND_SUFFICIENT", "effect": "WRITE"}], "agent_id": "human_service", "description": "Resolve support case objectives using verified case records.", "skills": [], "tools": [{"effect": "WRITE", "tool_id": "support_ticket_create"}, {"effect": "READ", "tool_id": "support_ticket_by_operation"}]}], "goal_descriptions": {"cancel_active_work": "Cancel one active conversation objective using its revises_control_id; this does not cancel an order.", "cancel_order": "Prepare cancellation of a specific order when the user requests that action; requires a bound order_id. Policy questions use general_qa.", "change_address": "Prepare an actual shipping-address change requested by the user; requires a bound order_id and explicitly supplied new_address. Questions about wh